// Generated by npm run build:pwa. Keep each version's app files together.
const CACHE_PREFIX = 'sequencepang2-shell-';
const CACHE_NAME = CACHE_PREFIX + '85e613a154b09db7';
const ASSETS = [
  "./app.js",
  "./campaign-data.js",
  "./engine.js",
  "./expansion-data.js",
  "./fonts/jua.woff",
  "./fonts/outfit.woff",
  "./icons/apple-touch-icon.png",
  "./icons/favicon-48.png",
  "./icons/icon-192.png",
  "./icons/icon-512.png",
  "./icons/maskable-512.png",
  "./index.html",
  "./levels.js",
  "./manifest.webmanifest",
  "./progress.js",
  "./pwa.js",
  "./sequencepang2-logo-v2.jpg",
  "./session.js",
  "./style.css"
];
const BASE = new URL('./', self.location.href);
const ASSET_URLS = new Set(ASSETS.map(path => new URL(path, BASE).href));

self.addEventListener('install', event => {
  event.waitUntil((async () => {
    try {
      const cache = await caches.open(CACHE_NAME);
      await cache.addAll(ASSETS.map(path => new Request(new URL(path, BASE), { cache: 'reload' })));
    } catch (error) {
      await caches.delete(CACHE_NAME);
      throw error;
    }
  })());
  // Updates wait until all old tabs close or the player chooses the home button.
});

self.addEventListener('activate', event => {
  event.waitUntil((async () => {
    for (const key of await caches.keys()) {
      if (key.startsWith(CACHE_PREFIX) && key !== CACHE_NAME) await caches.delete(key);
    }
    await self.clients.claim();
  })());
});

self.addEventListener('message', event => {
  if (event.data?.type === 'ACTIVATE_UPDATE') event.waitUntil(self.skipWaiting());
});

self.addEventListener('fetch', event => {
  if (event.request.method !== 'GET') return;
  const url = new URL(event.request.url);
  if (url.origin !== BASE.origin) return;
  url.search = '';
  const isHome = url.pathname === BASE.pathname || url.href === new URL('index.html', BASE).href;
  const key = isHome && event.request.mode === 'navigate' ? new URL('index.html', BASE).href : url.href;
  if (!ASSET_URLS.has(key)) return;
  event.respondWith((async () => {
    const cache = await caches.open(CACHE_NAME);
    return await cache.match(key) || fetch(event.request);
  })());
});
